// Criativo P — "Antes de impulsionar" (the same story as I, caught at the moment of deciding).
// Its own room: violet, white type centred with lime as the accent. It opens on the boost
// card with the cursor on its way to the button and a "PARA." that stops it; then the last
// campaign's statement, a budget slider that is not the answer, and the Radar's daily stack.
// Beats change with a vertical push. Synced to vo/17_tight.wav (word onsets). No sound twice.
import React from 'react';
import {AbsoluteFill} from 'remotion';
import {BACK, C, Cue, EXPO, EndCard, Grain, Kin, LogoMark, Mark, NightStage, Pointer, SANS, SfxTrack, Wordmark, endCardCues, k, useS, useT} from './kit';
import {Clock, Cover, LIN, PANEL, Scene} from './Ix';

export const P_DURATION = 23.2;

const W = {
  para: 0.05, antes: 0.73, de: 0.97, impulsionar: 1.07, de2: 1.51, novo: 1.63,
  da: 2.21, ultima: 2.31, vez: 2.61, foram: 2.81, trezentos: 3.09, e: 4.09, nenhuma: 4.16, venda: 4.54,
  voce: 4.92, nao: 5.14, precisa: 5.26, de3: 5.74, mais: 5.82, verba: 6.04, precisa2: 6.44, saber: 6.82, o: 7.24, que: 7.44, anunciar: 7.64,
  oCR: 8.26, creative: 8.34, te: 9.12, entrega: 9.2, dez: 9.66, criativos: 9.94, selecionados: 10.42, por: 11.0, dia: 11.22,
  ate: 11.62, trezentos2: 11.88, porMes: 12.38, mes: 12.54,
  sem: 13.04, voce2: 13.2, perder: 13.44, horas: 13.74, procurando: 13.98,
  q49: 14.87, noMes: 15.32, menos: 15.83, deM: 16.11, um70: 16.19, porD: 17.25, diaP: 17.43,
  marca: 17.75, clique: 18.61,
};
const B = {last: 2.12, need: 4.84, what: 6.36, radar: 8.18, hours: 12.96, price: 14.78, end: 17.7};
const LAND300 = 12.3;
const BEATS = [0, W.antes, B.last, W.nenhuma, B.need, B.what, B.radar, W.dez, LAND300, B.hours, B.price, B.end];
const SOFT_WHITE = 'rgba(255,255,255,0.7)';

export const CreativeP: React.FC = () => {
  const f = useT();
  const s = useS();
  const inS = (a: number, b: number) => f >= s(a) && f < s(b);
  const float = Math.sin(f / 26) * 6;
  const type = {f, s, mode: 'blur' as const, color: C.white, accent: C.lime};

  const cues: Cue[] = [
    {t: 0, s: 'impact', v: 0.3},
    {t: W.antes, s: 'glitch', v: 0.2},
    {t: W.novo, s: 'mech_click', v: 0.5},
    {t: B.last, s: 'whoosh_down', v: 0.26},
    {t: W.trezentos, s: 'coin', v: 0.36},
    {t: W.nenhuma, s: 'record_scratch', v: 0.22},
    {t: W.venda, s: 'drop_thud', v: 0.4},
    {t: B.need, s: 'swipe_ui', v: 0.32},
    {t: W.mais, s: 'slide', v: 0.36},
    {t: W.verba, s: 'snap', v: 0.42},
    {t: B.what, s: 'whoosh_soft', v: 0.28},
    {t: W.que, s: 'pop_a', v: 0.42},
    {t: W.anunciar, s: 'pop_c', v: 0.42},
    {t: B.radar, s: 'whoosh_fast', v: 0.28},
    {t: W.creative, s: 'shimmer', v: 0.2},
    {t: W.dez, s: 'hit_tight', v: 0.3},
    {t: W.criativos, s: 'card_flick', v: 0.4},
    {t: W.dia, s: 'tap_soft', v: 0.5},
    {t: W.ate, s: 'whoosh_long', v: 0.25},
    {t: LAND300, s: 'check', v: 0.32},
    {t: B.hours, s: 'air', v: 0.28},
    {t: W.horas, s: 'clock_tick', v: 0.5},
    {t: W.procurando, s: 'clock_tock', v: 0.5},
    {t: B.price, s: 'page_flip', v: 0.4},
    {t: W.q49, s: 'ding_score', v: 0.3},
    {t: W.um70, s: 'tick_ui', v: 0.5},
    {t: W.diaP, s: 'scan_ok', v: 0.34},
    ...endCardCues(B.end),
    {t: W.clique + 0.4, s: 'bookmark', v: 0.5},
  ];

  // beat 1: the cursor heads for the button and is stopped
  const go = k(f, -6, s(W.antes), 0, 1, EXPO);
  const frozen = k(f, s(W.antes), s(W.antes) + 6);
  const off = k(f, s(W.novo), s(W.novo) + 6);
  // beat 2: the statement
  const zero = k(f, s(W.nenhuma), s(W.nenhuma) + 8);
  // beat 3: the budget slider goes up and is refused
  const up = k(f, s(W.de3), s(W.verba)) - k(f, s(W.verba) + 2, s(W.verba) + 12);
  const refused = k(f, s(W.verba), s(W.verba) + 6);
  // beat 4: 10 → 300
  const swap = k(f, s(W.trezentos2), s(LAND300));
  const count = Math.round(k(f, s(W.dez), s(W.dia), 1, 10, LIN) + k(f, s(W.ate), s(LAND300), 0, 290));
  const px = k(f, s(W.clique) - 8, s(W.clique) + 10, 800, 612);
  const py = k(f, s(W.clique) - 8, s(W.clique) + 10, 1470, 1226);
  const press = k(f, s(W.clique) + 11, s(W.clique) + 14) - k(f, s(W.clique) + 14, s(W.clique) + 19);

  return (
    <AbsoluteFill style={{backgroundColor: '#4636BE', fontFamily: SANS}}>
      <NightStage beats={BEATS} look="violet" />

      {/* 1 — "Para! Antes de impulsionar de novo." (the stop is on frame 0) */}
      {inS(0, B.last) ? (
        <Scene f={f} a={-30} b={s(B.last)}>
          <div style={{position: 'absolute', left: 0, right: 0, top: 300, textAlign: 'center', fontSize: 270, fontWeight: 800, letterSpacing: -14, lineHeight: 1, color: C.lime, scale: String(k(f, 0, 9, 1.5, 1) * (1 + 0.05 * (k(f, s(W.para), s(W.para) + 3) - k(f, s(W.para) + 3, s(W.para) + 12)))), rotate: '-3deg'}}>PARA.</div>
          <Kin {...type} top={600} sizes={[84, 104]} lines={[[['Antes', W.antes], ['de', W.de], ['impulsionar', W.impulsionar, true]], [['de', W.de2], ['novo.', W.novo]]]} />
          <div style={{...PANEL, position: 'absolute', left: 140, top: 880 + float, width: 800, height: 500, borderRadius: 44, padding: 34, filter: `saturate(${1 - frozen * 0.5})`}}>
            <div style={{display: 'flex', gap: 28, alignItems: 'center'}}>
              <Cover i={3} w={150} />
              <div>
                <div style={{fontSize: 44, fontWeight: 800, letterSpacing: -1.6, color: C.ink}}>Impulsionar publicação</div>
                <div style={{fontSize: 34, color: C.muted, marginTop: 10}}>Orçamento</div>
                <div style={{fontSize: 64, fontWeight: 800, letterSpacing: -2.4, color: C.ink, lineHeight: 1.05}}>R$ 300</div>
              </div>
            </div>
            <div style={{marginTop: 30, height: 130, borderRadius: 65, boxSizing: 'border-box', display: 'grid', placeItems: 'center', fontSize: 54, fontWeight: 700, letterSpacing: -1.5, background: off > 0.5 ? C.white : C.purple, color: off > 0.5 ? C.muted : C.white, border: `4px ${off > 0.5 ? 'dashed' : 'solid'} ${off > 0.5 ? C.muted : C.purple}`, scale: String(1 - off * 0.04)}}>Impulsionar</div>
          </div>
          <Pointer x={980 - go * 330 + off * 60} y={1500 - go * 190 + off * 50} style={{scale: '1.5'}} />
        </Scene>
      ) : null}

      {/* 2 — "Da última vez foram trezentos reais. E nenhuma venda." (the statement) */}
      {inS(B.last, B.need) ? (
        <Scene f={f} a={s(B.last)} b={s(B.need)}>
          <Kin {...type} top={310} sizes={[84]} lines={[[['Da', W.da], ['última', W.ultima], ['vez', W.vez], ['foram', W.foram]]]} />
          <div style={{position: 'absolute', left: 0, right: 0, top: 410, textAlign: 'center', fontSize: 250, fontWeight: 800, letterSpacing: -12, lineHeight: 1, color: C.white, fontVariantNumeric: 'tabular-nums', opacity: k(f, s(W.trezentos) - 2, s(W.trezentos) + 3), scale: String(k(f, s(W.trezentos) - 2, s(W.trezentos) + 10, 1.25, 1))}}>
            <span style={{fontSize: 120, letterSpacing: -4, marginRight: 14}}>R$</span>300
          </div>
          <Kin {...type} top={690} sizes={[104]} lines={[[['e', W.e], ['nenhuma', W.nenhuma, true], ['venda.', W.venda, true]]]} />
          <div style={{...PANEL, position: 'absolute', left: 150, top: 900, width: 780, borderRadius: 36, padding: '30px 40px 14px', translate: `0px ${((1 - k(f, s(B.last), s(B.last) + 14)) * 80 + float).toFixed(1)}px`}}>
            <div style={{fontSize: 26, letterSpacing: 4, fontWeight: 700, color: C.muted}}>ÚLTIMA CAMPANHA</div>
            {([['Gasto', 'R$ 300,00', W.trezentos], ['Cliques', '96', W.trezentos + 0.3], ['Vendas', '0', W.nenhuma]] as [string, string, number][]).map(([label, value, at], i) => {
              const hit = i === 2;
              return (
                <div key={label} style={{display: 'flex', alignItems: 'center', justifyContent: 'space-between', height: hit ? 150 : 110, marginTop: hit ? 12 : 0, marginBottom: hit ? 16 : 0, padding: hit ? '0 26px' : 0, borderTop: hit ? undefined : `2px solid ${C.line}`, borderRadius: hit ? 26 : 0, background: hit && zero > 0 ? C.lav : undefined, border: hit ? `${1 + zero * 4}px solid ${zero > 0 ? C.purple : C.line}` : undefined, opacity: k(f, s(at), s(at) + 5), scale: String(hit ? 1 + zero * 0.04 : 1)}}>
                  <span style={{fontSize: 42, color: C.muted}}>{label}</span>
                  <span style={{fontSize: hit ? 120 : 56, fontWeight: 800, letterSpacing: -2, color: hit ? C.purple : C.ink, lineHeight: 1}}>{value}</span>
                </div>
              );
            })}
          </div>
        </Scene>
      ) : null}

      {/* 3a — "Você não precisa de mais verba." (the slider is not the answer) */}
      {inS(B.need, B.what) ? (
        <Scene f={f} a={s(B.need)} b={s(B.what)}>
          <Kin {...type} top={320} sizes={[88, 150]} lines={[[['Você', W.voce], ['não', W.nao], ['precisa', W.precisa]], [['de', W.de3], ['mais', W.mais], ['verba.', W.verba, true]]]} />
          <div style={{...PANEL, position: 'absolute', left: 120, top: 880 + float, width: 840, height: 360, borderRadius: 40, padding: '40px 46px', opacity: 1 - refused * 0.35}}>
            <div style={{display: 'flex', justifyContent: 'space-between', alignItems: 'baseline'}}>
              <span style={{fontSize: 40, color: C.muted}}>Verba</span>
              <span style={{fontSize: 96, fontWeight: 800, letterSpacing: -4, color: C.ink, fontVariantNumeric: 'tabular-nums', textDecoration: refused > 0.5 ? 'line-through' : undefined}}>R$ {Math.round(300 + up * 300)}</span>
            </div>
            <div style={{position: 'relative', height: 26, borderRadius: 13, background: C.lav2, marginTop: 60}}>
              <div style={{position: 'absolute', left: 0, top: 0, bottom: 0, width: `${34 + up * 50}%`, borderRadius: 13, background: C.purple}} />
              <div style={{position: 'absolute', left: `${34 + up * 50}%`, top: -27, width: 80, height: 80, marginLeft: -40, borderRadius: 40, background: C.white, border: `6px solid ${C.purple}`, boxSizing: 'border-box', boxShadow: '0 16px 30px -10px rgba(98,81,216,0.8)'}} />
            </div>
          </div>
        </Scene>
      ) : null}

      {/* 3b — "Precisa saber o que anunciar." */}
      {inS(B.what, B.radar) ? (
        <Scene f={f} a={s(B.what)} b={s(B.radar)}>
          <Kin {...type} top={320} sizes={[88, 170, 110]} lines={[[['Precisa', W.precisa2], ['saber', W.saber]], [['o', W.o, true], ['que', W.que, true]], [['anunciar.', W.anunciar]]]} />
          <div style={{position: 'absolute', left: 375, top: 900 + float, width: 330, height: 485, borderRadius: 30, border: '5px dashed rgba(255,255,255,0.7)', boxSizing: 'border-box', display: 'grid', placeItems: 'center', fontSize: 260, fontWeight: 800, color: C.lime, scale: String(k(f, s(W.saber), s(W.saber) + 10, 0.7, 1, BACK)), opacity: k(f, s(W.saber), s(W.saber) + 4)}}>
            <span style={{scale: String(1 + Math.sin(f / 5) * 0.05)}}>?</span>
          </div>
        </Scene>
      ) : null}

      {/* 4 — "O Creative Radar te entrega dez criativos selecionados por dia. Até trezentos por mês." (the daily stack) */}
      {inS(B.radar, B.hours) ? (
        <Scene f={f} a={s(B.radar)} b={s(B.hours)}>
          <div style={{position: 'absolute', left: 0, right: 0, top: 310, display: 'flex', justifyContent: 'center', alignItems: 'center', gap: 20}}>
            <LogoMark size={92} style={{scale: String(k(f, s(W.creative), s(W.creative) + 10, 0, 1, BACK))}} />
            <Wordmark f={f} at={s(W.creative) + 2} size={76} color={C.white} />
          </div>
          <Kin {...type} top={430} sizes={[76]} lines={[[['te', W.te], ['entrega', W.entrega]]]} />
          <div style={{position: 'absolute', left: 0, right: 0, top: 530, textAlign: 'center', fontSize: 52, fontWeight: 600, color: SOFT_WHITE, opacity: k(f, s(W.ate), s(W.ate) + 5)}}>até</div>
          <div style={{position: 'absolute', left: 90, top: 560, height: 300, width: 900, overflow: 'hidden', textAlign: 'center', fontSize: 310, fontWeight: 800, letterSpacing: -16, lineHeight: '300px', color: C.lime, fontVariantNumeric: 'tabular-nums'}}>
            <div style={{position: 'absolute', left: 0, right: 0, top: 0, translate: `0px ${((1 - k(f, s(W.dez), s(W.dez) + 9)) * 310 - swap * 310).toFixed(1)}px`}}>10</div>
            <div style={{position: 'absolute', left: 0, right: 0, top: 0, translate: `0px ${((1 - swap) * 310).toFixed(1)}px`}}>300</div>
          </div>
          <Kin {...type} top={866} sizes={[70]} lines={[[['criativos', W.criativos], ['selecionados', W.selecionados]]]} />
          <Kin {...type} top={950} sizes={[96]} out={W.ate + 0.1} lines={[[['por', W.por, true], ['dia.', W.dia, true]]]} />
          <Kin {...type} top={950} sizes={[96]} lines={[[['por', W.porMes, true], ['mês.', W.mes, true]]]} />
          <div style={{position: 'absolute', left: 430, top: 1090, width: 220, height: 323}}>
            {Array.from({length: 10}, (_, i) => {
              const a = s(W.dez) + i * 3;
              const p = k(f, a, a + 12);
              return <Cover key={i} i={i} w={220} style={{position: 'absolute', left: (1 - p) * 700 + ((i * 37) % 23) - 11, top: ((i * 53) % 19) - 9, rotate: `${((i * 47) % 13) - 6 + (1 - p) * 20}deg`, opacity: k(f, a, a + 3)}} />;
            })}
            <div style={{position: 'absolute', right: -70, top: -40, minWidth: 110, height: 110, padding: '0 22px', boxSizing: 'border-box', borderRadius: 55, background: C.lime, color: C.limeInk, fontSize: 56, fontWeight: 800, letterSpacing: -2, display: 'grid', placeItems: 'center', fontVariantNumeric: 'tabular-nums', boxShadow: '0 20px 40px -14px rgba(0,0,0,0.6)', scale: String(k(f, s(W.dez), s(W.dez) + 9, 0, 1, BACK))}}>{count}</div>
          </div>
        </Scene>
      ) : null}

      {/* 5 — "Sem você perder horas procurando." */}
      {inS(B.hours, B.price) ? (
        <Scene f={f} a={s(B.hours)} b={s(B.price)}>
          <Kin {...type} top={320} sizes={[88, 190, 92]} lines={[[['Sem', W.sem], ['você', W.voce2], ['perder', W.perder]], [['horas', W.horas, true]], [['procurando.', W.procurando]]]} />
          <div style={{position: 'absolute', left: 360, top: 900 + float, width: 360, height: 360}}>
            <Clock size={360} hours={k(f, s(B.hours), s(W.procurando), 0, 2.6, LIN)} ink={C.white} face="rgba(255,255,255,0.1)" accent={C.lime} />
            <div style={{position: 'absolute', right: -30, bottom: -20, width: 130, height: 130, borderRadius: 65, background: C.lime, display: 'grid', placeItems: 'center', scale: String(k(f, s(W.procurando), s(W.procurando) + 10, 0, 1, BACK)), boxShadow: '0 20px 40px -14px rgba(0,0,0,0.6)'}}>
              <svg width="70" height="70" viewBox="0 0 24 24" fill="none" stroke={C.limeInk} strokeWidth="3.4" strokeLinecap="round" strokeLinejoin="round">
                <path d="M5 12.5l4.5 4.5L19 7.5" />
              </svg>
            </div>
          </div>
        </Scene>
      ) : null}

      {/* 6 — "Quarenta e nove reais no mês. Menos de um real e setenta por dia." */}
      {inS(B.price, B.end) ? (
        <Scene f={f} a={s(B.price)} b={s(B.end)}>
          <div style={{position: 'absolute', left: 0, right: 0, top: 320, display: 'flex', justifyContent: 'center', alignItems: 'baseline', color: C.white, fontWeight: 800, lineHeight: 1, opacity: k(f, s(W.q49) - 2, s(W.q49) + 3), scale: String(k(f, s(W.q49) - 2, s(W.q49) + 10, 1.25, 1))}}>
            <span style={{fontSize: 120, letterSpacing: -4, marginRight: 12}}>R$</span>
            <span style={{fontSize: 290, letterSpacing: -15}}>49</span>
          </div>
          <div style={{position: 'absolute', left: 0, right: 0, top: 620, textAlign: 'center', fontSize: 64, fontWeight: 600, letterSpacing: -2, color: SOFT_WHITE, opacity: k(f, s(W.noMes), s(W.noMes) + 5)}}>no mês</div>
          <Kin {...type} top={760} sizes={[84, 140]} lines={[[['Menos', W.menos], ['de', W.deM]], [['R$ 1,70', W.um70, true]]]} />
          <Kin {...type} top={1010} sizes={[96]} lines={[[['por', W.porD], ['dia.', W.diaP]]]} />
          <div style={{position: 'absolute', left: 0, right: 0, top: 1200, display: 'flex', justifyContent: 'center', opacity: k(f, s(W.um70) + 6, s(W.um70) + 12)}}>
            <div style={{padding: '20px 40px', borderRadius: 99, background: 'rgba(255,255,255,0.14)', border: '2px solid rgba(255,255,255,0.3)', color: C.white, fontSize: 44, fontWeight: 600, letterSpacing: -1}}>R$ 49 ÷ 30 dias</div>
          </div>
        </Scene>
      ) : null}

      {/* 7 — "Creative Radar. Clique no link e compre agora." */}
      {f >= s(B.end) ? (
        <>
          <EndCard f={f} at={s(B.end)} theme="dark" offer={['10 criativos por dia', 'R$ 49 por mês']} cta="Compre agora" bare />
          <Pointer x={px} y={py} press={press} style={{opacity: k(f, s(W.clique) - 8, s(W.clique) - 3)}} />
        </>
      ) : null}

      {f < s(B.end) ? <Mark color={C.white} /> : null}
      <AbsoluteFill style={{background: C.white, opacity: f >= s(B.end) ? k(f, s(B.end), s(B.end) + 6, 0.4, 0) : 0, pointerEvents: 'none'}} />
      <Grain opacity={0.05} />
      <SfxTrack cues={cues} />
    </AbsoluteFill>
  );
};

// Shared design kit for the five Creative Radar motion creatives.
// Identity (colours, type, logo, end card, sonic logo) lives here; each creative
// brings its own motion language on top of it.
import React, {createContext, useContext} from 'react';
import {AbsoluteFill, Audio, Easing, Img, Sequence, interpolate, staticFile, useCurrentFrame, useVideoConfig} from 'remotion';

export const C = {
  ink: '#202124',
  muted: '#686B75',
  line: '#E9E9EC',
  purple: '#6251D8',
  purple2: '#8B7CF0',
  lav: '#F2EFFF',
  lav2: '#E6E0FF',
  lime: '#C9F58B',
  limeInk: '#203014',
  limeDeep: '#7CC23A',
  dark: '#15121F',
  dark2: '#221D38',
  paper: '#FAFAFB',
  white: '#FFFFFF',
};
export const SANS = '-apple-system, "SF Pro Display", "Helvetica Neue", Inter, Arial, sans-serif';

// Reels/TikTok safe area on 1080×1920 (from the user's template). Information
// stays inside; backgrounds may bleed. Below LOW_Y the right action rail eats 140px.
export const SAFE = {top: 296, bottom: 1534, left: 54, right: 1026, rightLow: 941, lowY: 1142};
// Content column used by every creative: inside both widths of the safe area.
export const COL = {x0: 90, x1: 930, w: 840, cx: 510};

export const EXPO = Easing.bezier(0.16, 1, 0.3, 1);
export const EXPO_IN = Easing.bezier(0.7, 0, 0.84, 0);
export const INOUT = Easing.bezier(0.83, 0, 0.17, 1);
export const BACK = Easing.bezier(0.34, 1.56, 0.64, 1);
export const SOFT = Easing.bezier(0.45, 0, 0.55, 1);

export const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v));
export const k = (f: number, a: number, b: number, from = 0, to = 1, ease: (t: number) => number = EXPO) =>
  interpolate(f, [a, b], [from, to], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease});

// seconds → frame, the one clock every creative uses (data is in seconds).
export const useS = () => {
  const {fps} = useVideoConfig();
  return (sec: number) => Math.round(sec * fps);
};

// Standard entrance: rise + unblur + fade, settles hard.
export const enter = (f: number, at: number, len = 12, dist = 60, axis: 'y' | 'x' = 'y'): React.CSSProperties => {
  const p = k(f, at, at + len);
  const d = ((1 - p) * dist).toFixed(1);
  return {
    opacity: k(f, at, at + len * 0.5),
    translate: axis === 'y' ? `0px ${d}px` : `${d}px 0px`,
    filter: `blur(${((1 - p) * 10).toFixed(2)}px)`,
  };
};
export const leave = (f: number, at: number, len = 8, dist = -40): React.CSSProperties => {
  const p = k(f, at, at + len, 0, 1, EXPO_IN);
  return {opacity: 1 - p, translate: `0px ${(p * dist).toFixed(1)}px`, filter: `blur(${(p * 8).toFixed(2)}px)`};
};
// merge two style objects that both animate opacity/translate/filter (enter then leave)
export const both = (a: React.CSSProperties, b: React.CSSProperties): React.CSSProperties => {
  const oa = (a.opacity as number) ?? 1;
  const ob = (b.opacity as number) ?? 1;
  const pa = String(a.translate ?? '0px 0px').split(' ').map(parseFloat);
  const pb = String(b.translate ?? '0px 0px').split(' ').map(parseFloat);
  const ba = parseFloat(String(a.filter ?? 'blur(0px)').replace(/[^0-9.]/g, '')) || 0;
  const bb = parseFloat(String(b.filter ?? 'blur(0px)').replace(/[^0-9.]/g, '')) || 0;
  return {opacity: oa * ob, translate: `${pa[0] + pb[0]}px ${pa[1] + pb[1]}px`, filter: `blur(${ba + bb}px)`};
};

// ------------------------------------------------------------------ sound
export type Cue = {t: number; s: string; v?: number};
// Time-warp for the narrated cut: visuals are rendered at a remapped frame (see
// Final.tsx) and SFX cue times are pushed through the same map, so sound stays
// glued to the picture. `mute` silences SFX in the visual pass; `sfxOnly` makes a
// creative render nothing but its SfxTrack.
type Warp = {map: (t: number) => number; mute: boolean; sfxOnly: boolean; real?: number; speed?: number};
export const WarpCtx = createContext<Warp>({map: (t) => t, mute: false, sfxOnly: false});
export const useSfxOnly = () => useContext(WarpCtx).sfxOnly;
// The clock of the narrated creatives (H onwards): the composition frame times the playback
// speed of a faster cut (Fast.tsx). Fractional, so a 1.5× cut drops no frames.
export const useT = () => {
  const speed = useContext(WarpCtx).speed ?? 1;
  return useCurrentFrame() * speed;
};
// the composition frame BEFORE the time-warp (for idle loops that should keep a constant speed)
export const useRealFrame = () => {
  const r = useContext(WarpCtx).real;
  const f = useCurrentFrame();
  return r ?? f;
};
export const SfxTrack: React.FC<{cues: Cue[]}> = ({cues}) => {
  const {fps} = useVideoConfig();
  const warp = useContext(WarpCtx);
  if (warp.mute) return null;
  return (
    <>
      {cues.map((c, i) => (
        <Sequence key={i} from={Math.max(0, Math.round(warp.map(c.t) * fps))} durationInFrames={Math.round(3.5 * fps)} layout="none">
          <Audio src={staticFile(`sfx/${c.s}.wav`)} volume={c.v ?? 0.5} />
        </Sequence>
      ))}
    </>
  );
};
// keystrokes for a typed string: alternates the four key samples, space gets its own
export const typingCues = (text: string, t0: number, cps: number, v = 0.32, del = false): Cue[] =>
  text.split('').map((ch, i) => ({
    t: t0 + i / cps,
    s: del ? 'key_del' : ch === ' ' ? 'key_space' : `key_${(i * 7) % 4 + 1}`,
    v: v * (0.8 + ((i * 13) % 5) * 0.06),
  }));

