// Moving background for the narrated creatives (H onwards). Everything is brand material —
// glow, the grid, radar rings, a touch of lime — but nothing sits still: soft light beams
// sway from the top-left corner, three rings ripple out from below the frame, the grid
// slides, and every beat (seconds, in `beats`) kicks the stage: the glow jumps to a new
// spot, the grid whips sideways and a light streak crosses. Kept to a few quiet layers so
// it never competes with the type. `dark` = [from, to] seconds with the lights off.
// `look` gives each creative its own room: night (H), paper (light), violet, ink, dusk.
type StageLook = {base: string; glow: string; glowA: number; glow2: string; beam: string | null; ring: string | null; grid: 'lines' | 'dots' | 'rows' | null; gridColor: string; streak: string; vignette: string; corner: string};
export const STAGE: Record<'night' | 'paper' | 'violet' | 'ink' | 'dusk', StageLook> = {
  night: {base: C.dark, glow: '98,81,216', glowA: 0.5, glow2: 'rgba(139,124,240,0.13)', beam: '139,124,240', ring: '173,160,255', grid: 'lines', gridColor: 'rgba(255,255,255,0.045)', streak: '173,160,255', vignette: 'rgba(8,6,14,0.6)', corner: `${C.lime}14`},
  paper: {base: '#FBFAFF', glow: '139,124,240', glowA: 0.3, glow2: 'rgba(201,245,139,0.14)', beam: null, ring: '98,81,216', grid: 'lines', gridColor: 'rgba(98,81,216,0.07)', streak: '139,124,240', vignette: 'rgba(98,81,216,0.1)', corner: `${C.lime}40`},
  violet: {base: '#4636BE', glow: '139,124,240', glowA: 0.7, glow2: 'rgba(28,18,84,0.5)', beam: '255,255,255', ring: '255,255,255', grid: null, gridColor: '', streak: '255,255,255', vignette: 'rgba(24,14,74,0.55)', corner: `${C.lime}26`},
  ink: {base: '#101014', glow: '74,76,104', glowA: 0.4, glow2: 'rgba(98,81,216,0.07)', beam: null, ring: null, grid: 'dots', gridColor: 'rgba(255,255,255,0.11)', streak: '139,124,240', vignette: 'rgba(0,0,0,0.6)', corner: `${C.lime}0c`},
  dusk: {base: '#1D1833', glow: '139,124,240', glowA: 0.3, glow2: 'rgba(98,81,216,0.28)', beam: null, ring: '173,160,255', grid: 'rows', gridColor: 'rgba(255,255,255,0.075)', streak: '201,245,139', vignette: 'rgba(10,8,22,0.6)', corner: `${C.lime}10`},
};
const STAGE_SPOTS: [number, number][] = [[50, 38], [24, 30], [76, 34], [38, 50], [66, 26], [50, 52], [28, 42], [72, 46]];
export const NightStage: React.FC<{beats: number[]; dark?: [number, number]; look?: keyof typeof STAGE}> = ({beats, dark, look = 'night'}) => {
  const L = STAGE[look];
  const f = useT();
  const {fps} = useVideoConfig();
  const bf = beats.map((b) => Math.round(b * fps));
  let idx = 0;
  bf.forEach((b, i) => {
    if (f >= b) idx = i;
  });
  const kick = 1 - k(f, bf[idx], bf[idx] + 16);
  const move = k(f, bf[idx], bf[idx] + 20);
  const from = STAGE_SPOTS[(idx + STAGE_SPOTS.length - 1) % STAGE_SPOTS.length];
  const to = STAGE_SPOTS[idx % STAGE_SPOTS.length];
  const gx = from[0] + (to[0] - from[0]) * move + Math.sin(f / 37) * 5;
  const gy = from[1] + (to[1] - from[1]) * move + Math.cos(f / 29) * 4;
  const on = dark ? clamp(1 - k(f, Math.round(dark[0] * fps), Math.round(dark[0] * fps) + 3) + k(f, Math.round(dark[1] * fps), Math.round(dark[1] * fps) + 15), 0, 1) : 1;
  // the grid slides all the time and jumps 2.5 modules on every beat, alternating axis
  const jump = bf.reduce((acc, b, i) => (i % 2 === 0 ? [acc[0] + k(f, b, b + 14) * 165, acc[1]] : [acc[0], acc[1] + k(f, b, b + 14) * 165]), [0, 0]);
  const streak = k(f, bf[idx], bf[idx] + 9, 0, 1, SOFT);
  const gridImage =
    L.grid === 'dots'
      ? `radial-gradient(${L.gridColor} 2.5px, transparent 2.5px)`
      : L.grid === 'rows'
        ? `linear-gradient(${L.gridColor} 2px, transparent 2px)`
        : `linear-gradient(${L.gridColor} 1px, transparent 1px), linear-gradient(90deg, ${L.gridColor} 1px, transparent 1px)`;
  return (
    <AbsoluteFill style={{backgroundColor: L.base, overflow: 'hidden'}}>
      <AbsoluteFill style={{opacity: on, scale: String(1 + kick * 0.04)}}>
        <AbsoluteFill style={{background: `radial-gradient(circle at ${gx.toFixed(1)}% ${gy.toFixed(1)}%, rgba(${L.glow},${(L.glowA + kick * 0.14).toFixed(2)}) 0%, transparent ${(52 + kick * 6).toFixed(1)}%), radial-gradient(circle at ${(100 - gx + Math.sin(f / 53) * 10).toFixed(1)}% ${(72 + Math.cos(f / 41) * 8).toFixed(1)}%, ${L.glow2} 0%, transparent 40%), radial-gradient(circle at 96% 102%, ${L.corner} 0%, transparent 24%)`}} />
        {/* light beams from the top-left corner */}
        {L.beam ? (
          <AbsoluteFill style={{background: `repeating-conic-gradient(from ${(96 + Math.sin(f / 48) * 9 + f * 0.1).toFixed(2)}deg at -6% -4%, rgba(${L.beam},0.085) 0deg 2.6deg, transparent 2.6deg 9deg, rgba(${L.beam},0.045) 9deg 10.4deg, transparent 10.4deg 19deg)`, maskImage: 'radial-gradient(circle at 0% 0%, black 0%, rgba(0,0,0,0.5) 45%, transparent 78%)', filter: 'blur(7px)', opacity: 0.75 + kick * 0.25}} />
        ) : null}
        {/* radar rings rippling out from below the frame */}
        {L.ring ? (
          <div style={{position: 'absolute', left: 540, top: 1840}}>
            {[0, 1, 2].map((i) => {
              const r = 220 + ((f * 2.4 + i * 460) % 1380);
              return <div key={i} style={{position: 'absolute', left: -r, top: -r, width: r * 2, height: r * 2, borderRadius: '50%', border: `2px ${i % 2 ? 'dashed' : 'solid'} rgba(${L.ring},${((1 - (r - 220) / 1380) * 0.16).toFixed(3)})`}} />;
            })}
          </div>
        ) : null}
        {L.grid ? (
          <AbsoluteFill style={{maskImage: 'radial-gradient(ellipse 80% 62% at 50% 45%, black 15%, transparent 82%)'}}>
            <AbsoluteFill style={{backgroundImage: gridImage, backgroundSize: L.grid === 'dots' ? '44px 44px' : '66px 66px', backgroundPosition: `${(f * 0.7 + jump[0]).toFixed(1)}px ${(f * 1.1 + jump[1]).toFixed(1)}px`}} />
          </AbsoluteFill>
        ) : null}
        {/* light streak across the frame on every beat */}
        <div style={{position: 'absolute', left: -700 + streak * 2400, top: -500, width: 380, height: 3000, rotate: '22deg', background: `linear-gradient(90deg, transparent, rgba(${L.streak},0.15), transparent)`, filter: 'blur(26px)', opacity: Math.sin(Math.PI * streak)}} />
      </AbsoluteFill>
      <AbsoluteFill style={{background: `radial-gradient(ellipse 95% 80% at 50% 46%, transparent 55%, ${L.vignette} 100%)`}} />
    </AbsoluteFill>
  );
};

// ------------------------------------------------------------------ kinetic type
// [word, onset in seconds, accent?]. Each word lands on its own onset; the block leaves as
// one. `mode` is the voice of the piece: blur (out of focus, H), rise (slides up from behind
// a mask), bar (accent words sit on a solid highlight bar, the rest pop).
export type Wd = [string, number, boolean?];
export const Kin: React.FC<{
  f: number;
  s: (x: number) => number;
  lines: Wd[][];
  top: number;
  sizes: number[];
  out?: number;
  dim?: number;
  color?: string;
  accent?: string;
  barInk?: string;
  align?: 'center' | 'left';
  mode?: 'blur' | 'rise' | 'bar';
  left?: number;
  right?: number;
}> = ({f, s, lines, top, sizes, out, dim = 1, color = C.white, accent = C.lime, barInk = C.limeInk, align = 'center', mode = 'blur', left = 70, right = 70}) => {
  const q = out === undefined ? 0 : k(f, s(out) - 5, s(out), 0, 1, EXPO_IN);
  return (
    <div style={{position: 'absolute', top, left, right, textAlign: align, fontFamily: SANS, fontWeight: 700, color, opacity: (1 - q) * dim, translate: `0px ${(-q * 80).toFixed(1)}px`, filter: `blur(${(q * 14).toFixed(2)}px)`}}>
      {lines.map((ln, li) => {
        const sz = sizes[li] ?? sizes[0];
        const gap = align === 'left' ? `0 ${(sz * 0.22).toFixed(1)}px 0 0` : `0 ${(sz * 0.11).toFixed(1)}px`;
        return (
          <div key={li} style={{fontSize: sz, letterSpacing: -sz * 0.045, lineHeight: mode === 'bar' ? 1.22 : 1.08}}>
            {ln.map(([w, t, acc], i) => {
              const a = s(t);
              const p = k(f, a, a + 7);
              if (mode === 'rise') {
                return (
                  <span key={i} style={{display: 'inline-block', overflow: 'hidden', verticalAlign: 'bottom', margin: gap, paddingBottom: sz * 0.14, marginBottom: -sz * 0.14, color: acc ? accent : undefined}}>
                    <span style={{display: 'inline-block', translate: `0px ${((1 - k(f, a, a + 9)) * 115).toFixed(1)}%`}}>{w}</span>
                  </span>
                );
              }
              if (mode === 'bar') {
                const pop = k(f, a, a + 8, 0, 1, BACK);
                return acc ? (
                  <span key={i} style={{display: 'inline-block', position: 'relative', padding: `0 ${(sz * 0.14).toFixed(1)}px`, margin: `0 ${(sz * 0.02).toFixed(1)}px`, color: barInk, opacity: k(f, a, a + 2)}}>
                    <span style={{position: 'absolute', inset: '9% 0 7% 0', borderRadius: sz * 0.14, background: accent, transformOrigin: '0% 50%', scale: `${k(f, a, a + 6)} 1`}} />
                    <span style={{position: 'relative'}}>{w}</span>
                  </span>
                ) : (
                  <span key={i} style={{display: 'inline-block', margin: gap, opacity: k(f, a, a + 3), scale: String(0.6 + pop * 0.4)}}>
                    {w}
                  </span>
                );
              }
              return (
                <span key={i} style={{display: 'inline-block', margin: gap, color: acc ? accent : undefined, opacity: k(f, a, a + 3), translate: `0px ${((1 - p) * sz * 0.4).toFixed(1)}px`, scale: String(1.2 - p * 0.2), filter: `blur(${((1 - p) * 12).toFixed(2)}px)`}}>
                  {w}
                </span>
              );
            })}
          </div>
        );
      })}
    </div>
  );
};

