// Headline block used for on-screen text. `parts` = [text, accent?]. Words enter one by one.
export const Headline: React.FC<{
  f: number;
  at: number;
  lines: [string, boolean?][][];
  size?: number;
  color?: string;
  accent?: string;
  align?: 'left' | 'center';
  top: number;
  stagger?: number;
  out?: number | null;
}> = ({f, at, lines, size = 88, color = C.ink, accent = C.purple, align = 'left', top, stagger = 3, out = null}) => {
  let i = 0;
  const lv = out === null ? {} : leave(f, out);
  return (
    <div
      style={{
        position: 'absolute',
        top,
        left: COL.x0,
        width: COL.w,
        textAlign: align,
        fontFamily: SANS,
        fontSize: size,
        fontWeight: 700,
        letterSpacing: -size * 0.045,
        lineHeight: 1.04,
        color,
        ...lv,
      }}
    >
      {lines.map((ln, li) => (
        <div key={li}>
          {ln.map(([w, acc]) => {
            const idx = i++;
            return (
              <span key={idx} style={{display: 'inline-block', marginRight: size * 0.24, color: acc ? accent : undefined, ...enter(f, at + idx * stagger, 12, size * 0.6)}}>
                {w}
              </span>
            );
          })}
        </div>
      ))}
    </div>
  );
};
export const words = (s: string, accentFrom = Infinity): [string, boolean?][] => s.split(' ').map((w, i) => [w, i >= accentFrom]);

// Shared scene pieces for the four pieces that grew out of creative I (M, N, O, P). Each of them
// has its own room, type voice and objects; what they have in common lives here.
import React from 'react';
import {AdCard, C, EXPO_IN, REAL_ADS, k} from './kit';

export const PANEL: React.CSSProperties = {background: C.white, border: `1px solid ${C.line}`, boxShadow: '0 40px 80px -40px rgba(98,81,216,0.45)', boxSizing: 'border-box'};
export const LIN = (t: number) => t;

// one beat on screen from frame a to frame b; `kind` is how the piece changes beats
export const Scene: React.FC<{f: number; a: number; b: number; kind?: 'up' | 'side' | 'zoom'; children: React.ReactNode}> = ({f, a, b, kind = 'up', children}) => {
  const p = k(f, a, a + 10);
  const q = k(f, b - 6, b, 0, 1, EXPO_IN);
  const move: React.CSSProperties =
    kind === 'up'
      ? {translate: `0px ${((1 - p) * 240 - q * 420).toFixed(1)}px`}
      : kind === 'side'
        ? {translate: `${((1 - p) * 320 - q * 520).toFixed(1)}px 0px`}
        : {scale: String(0.88 + p * 0.12 + q * 0.2), filter: `blur(${((1 - p) * 10 + q * 12).toFixed(1)}px)`};
  return <div style={{position: 'absolute', inset: 0, opacity: k(f, a, a + 4) * (1 - q), ...move}}>{children}</div>;
};

// analog clock; `hours` is the time elapsed (the minute hand makes one turn per hour)
export const Clock: React.FC<{size: number; hours: number; ink: string; face: string; accent: string; style?: React.CSSProperties}> = ({size, hours, ink, face, accent, style}) => (
  <svg width={size} height={size} viewBox="0 0 100 100" style={style}>
    <circle cx="50" cy="50" r="46" fill={face} stroke={ink} strokeWidth="4" />
    {Array.from({length: 12}, (_, i) => (
      <line key={i} x1="50" y1="9" x2="50" y2={i % 3 === 0 ? 17 : 13} stroke={ink} strokeWidth={i % 3 === 0 ? 3 : 1.6} strokeLinecap="round" transform={`rotate(${i * 30} 50 50)`} />
    ))}
    <line x1="50" y1="50" x2="50" y2="28" stroke={ink} strokeWidth="5" strokeLinecap="round" transform={`rotate(${(hours * 30).toFixed(1)} 50 50)`} />
    <line x1="50" y1="50" x2="50" y2="15" stroke={accent} strokeWidth="3.4" strokeLinecap="round" transform={`rotate(${(hours * 360).toFixed(1)} 50 50)`} />
    <circle cx="50" cy="50" r="4.5" fill={ink} />
  </svg>
);
export const hm = (min: number) => {
  const m = Math.max(0, Math.round(min));
  return `${Math.floor(m / 60)}h ${String(m % 60).padStart(2, '0')}min`;
};

