// search field of the app: the niche is typed from frame `at`, the button presses at `press`
export const SearchPill: React.FC<{f: number; at: number; press: number; text?: string; style?: React.CSSProperties}> = ({f, at, press, text = 'seu nicho', style}) => {
  const shown = Math.max(0, Math.min(text.length, Math.floor((f - at) / 1.6)));
  const down = k(f, press, press + 3) - k(f, press + 3, press + 9);
  return (
    <div style={{...PANEL, position: 'absolute', left: 90, width: 840, height: 132, borderRadius: 66, display: 'flex', alignItems: 'center', padding: '0 16px 0 40px', gap: 22, ...style}}>
