        <circle cx="11" cy="11" r="7" />
        <path d="M20 20l-4-4" />
      </svg>
      <div style={{flex: 1, fontSize: 50, fontWeight: 600, letterSpacing: -1.4, color: C.ink, whiteSpace: 'nowrap'}}>
        {text.slice(0, shown)}
        <span style={{display: 'inline-block', width: 4, height: 54, marginLeft: 4, background: C.purple, verticalAlign: 'middle', opacity: f >= at && f < press && Math.floor(f / 8) % 2 === 0 ? 1 : 0}} />
      </div>
      <div style={{height: 100, padding: '0 44px', borderRadius: 50, background: C.purple, color: C.white, fontSize: 42, fontWeight: 700, letterSpacing: -1, display: 'grid', placeItems: 'center', scale: String(1 - down * 0.08)}}>Buscar</div>
    </div>
  );
};

// Faster cuts of the narrated creatives (H–L): the same composition played at `speed`×.
// The creatives read their clock from useT() (kit), which multiplies the frame by `speed`, so
// the picture advances `speed` animation frames per output frame — fractional, nothing dropped.
// SFX cues are placed at time ÷ speed and play at their natural pitch. The voice is sped up
// separately by tools/tighten.py (--tempo, pitch kept) and mixed with the music in tools/mix.sh.
import React from 'react';
import {WarpCtx} from './kit';

// [composition suffix, speed]
export const SPEEDS: [string, number][] = [
  ['x125', 1.25],
  ['x15', 1.5],
];

export const fast = (Comp: React.FC, speed: number): React.FC => () => (
  <WarpCtx.Provider value={{map: (t) => t / speed, mute: false, sfxOnly: false, speed}}>
    <Comp />
  </WarpCtx.Provider>
);

import React from "react";
import { Composition, registerRoot } from "remotion";
